import re,glob,sys
D='/home/claude/book/ms/'
def latest(ch):
    c=sorted(glob.glob(D+ch+'-v*.md'),key=lambda p:int(re.search(r'-v(\d+)\.md$',p).group(1)))
    return c[-1]
def apply(ch,edits):
    src=latest(ch); n=int(re.search(r'-v(\d+)\.md$',src).group(1))+1
    t=open(src,encoding='utf-8').read()
    for i,(o,nw) in enumerate(edits):
        c=t.count(o)
        if c!=1: print('FAIL',ch,i,'count',c,o[:50]); sys.exit(1)
        t=t.replace(o,nw)
    out=D+f'{ch}-v{n}.md'; open(out,'w',encoding='utf-8').write(t); print('ok',out)
